'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={translation:'Traducción',session:'Contexto',native:'DuckDB nativa',verified:'Forma verificada',partial:'Parcial',catalog:'Catalogada'};
const types={scalar:'Escalares',aggregate:'Agregación',table:'Tabulares',macro:'Macros',table_macro:'Macros tabulares',pragma:'Pragma y utilidades'};
const badge=(v,label)=>`<span class="badge ${v}">${label||labels[v]||esc(v)}</span>`;
const path=i=>i.origin==='reference'?`#statement/${encodeURIComponent(i.id)}`:i.origin==='native'?`#function/native/${encodeURIComponent(i.name)}`:`#function/emulator/${encodeURIComponent(i.name)}`;
const highlight=s=>esc(s).replace(/(&#39;.*?&#39;)/g,'<span class="str">$1</span>').replace(/\b(SELECT|FROM|AS|CAST|DATE|NULL|IF|IS|NOT|INTERVAL|CREATE|OR|REPLACE|FUNCTION|RETURNS|LANGUAGE|SQL|DROP|SHOW|WHERE|TRUE|FALSE)\b/g,'<span class="kw">$1</span>');
let codeCount=0,codeMap={};
function code(s,label='SQL'){const id=++codeCount;codeMap[id]=s;return `<pre><div class="code-label">${esc(label)}</div><button class="copy" data-copy="${id}" aria-label="Copiar ${esc(label)}">Copiar</button><code${(label==='CONTEXTO DEL EMULADOR'||(label==='RESULTADO / REFERENCIA'&&/^(Usuario de la sesión|Rol de la sesión|Fecha de ejecución|Timestamp de ejecución)$/.test(s)))?' data-i18n-prose':''}>${highlight(s)}</code></pre>`;}
const meta=()=>`<div class="page-meta"><span>Referencia SQL</span><span>DuckDB 1.5.5</span><span>Auditoría · 21 oct 2026</span></div>`;
const notice=(s,w=false)=>`<div class="notice ${w?'warning':''}"><span class="notice-icon">${w?'△':'ⓘ'}</span><p>${s}</p></div>`;
let references=[],native=[],emulator=[],all=[],page=1,filterOrigin='all',filterType='all',filterStatus='all',query='',route='overview';
const content=$('#content');
function heading(kicker,title,description){return `<p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="lead">${description}</p>${meta()}`;}
function toc(entries){$('#tocLinks').innerHTML=entries.map(([id,t])=>`<a href="${location.hash.split('?')[0]||'#overview'}?section=${id}" data-scroll="${id}">${t}</a>`).join('');}
function emuTable(items){return `<div class="table-wrap"><table><thead><tr><th>Función</th><th>Implementación</th><th>Estado</th></tr></thead><tbody>${items.map(i=>`<tr><td class="function-name"><a href="${path(i)}">${esc(i.name)}</a><div class="type-label">${esc(i.category)}</div></td><td><code${i.origin==='session'?' data-i18n-prose':''}>${esc(i.target)}</code></td><td>${badge(i.status)}</td></tr>`).join('')}</tbody></table></div>`;}
function overview(){content.innerHTML=heading('REFERENCIA SQL','Referencia SQL del emulador','Explorá consultas, comandos, tipos de datos y funciones admitidos por el emulador, con sus diferencias y limitaciones.')+`<div class="sql-summary"><a href="#sql/query">Sintaxis de consultas →</a><a href="#statement/with">WITH (CTE) →</a><a href="#statement/copy-into">COPY INTO →</a><a href="#sql">35 referencias SQL →</a></div><div class="stats"><div class="stat"><strong>947</strong><span>Nombres nativos de DuckDB</span><small>Incluye operadores y utilidades</small></div><div class="stat"><strong>13</strong><span>Traducciones Snowflake</span><small>Adaptadas por el emulador</small></div><div class="stat"><strong>2</strong><span>Funciones de contexto</span><small>Usuario y rol de la sesión</small></div></div>`+notice('<strong>Disponibilidad ≠ compatibilidad completa.</strong> El catálogo nativo muestra lo que registra el motor. Las traducciones adaptan un subconjunto de sintaxis; cada ficha detalla su alcance y sus diferencias.')+`<h2 id="origins">Dos capas, una referencia</h2><p>El emulador adapta las llamadas que reconoce y envía el resto de la consulta a DuckDB. Elegí una capa para conocer cómo se resuelve cada función.</p><div class="table-wrap"><table><thead><tr><th>Origen</th><th>Qué incluye</th><th>Referencia</th></tr></thead><tbody><tr><td>${badge('translation')}</td><td class="description">13 funciones reescritas a expresiones de DuckDB.</td><td><a href="#translations">Ver traducciones →</a></td></tr><tr><td>${badge('native')}</td><td class="description">Funciones, operadores y macros registrados en el motor.</td><td><a href="#native">Explorar catálogo →</a></td></tr><tr><td>${badge('session')}</td><td class="description">2 funciones resueltas por la sesión del emulador.</td><td><a href="#session">Ver contexto →</a></td></tr></tbody></table></div><div class="section-head"><h2 id="translated">Funciones del emulador</h2><a href="#translations">Ver las 13 traducciones →</a></div><p class="lead">Traducciones y funciones de contexto. Abrí una función para ver su sintaxis, un ejemplo y las limitaciones conocidas.</p>${emuTable(emulator)}<h2 id="native-overview">Funciones nativas de DuckDB</h2><p>Los nombres que no se transforman llegan al motor con su sintaxis original. Las firmas, tipos y extensiones determinan qué consultas pueden ejecutarse.</p>${nativeTypes()}<h2 id="read-status">Cómo leer los estados</h2><p>${badge('verified')} Se ejecutó una forma concreta o existe una prueba automatizada. ${badge('partial')} Hay restricciones conocidas. ${badge('native','Catalogada')} Figura en DuckDB; no se probó cada firma a través del emulador.</p><div class="overview-bottom"><a href="#limits">Consultar limitaciones →</a><a href="#udf">Crear una función SQL →</a></div>`;toc([['origins','Origen de las funciones'],['translated','Funciones del emulador'],['native-overview','Catálogo DuckDB'],['read-status','Estados de soporte']]);}
function nativeTypes(){return `<div class="table-wrap"><table><thead><tr><th>Categoría del motor</th><th>Nombres</th><th>Descripción</th></tr></thead><tbody>${Object.entries(types).map(([t,l])=>`<tr><td><a href="#native/${t}">${l}</a></td><td>${native.filter(i=>i.types.includes(t)).length}</td><td class="description">${({scalar:'Operan sobre valores individuales.',aggregate:'Calculan un valor por grupo.',table:'Producen conjuntos de filas.',macro:'Expresiones SQL reutilizables.',table_macro:'Macros que producen tablas.',pragma:'Inspección y configuración del motor.'})[t]}</td></tr>`).join('')}</tbody></table></div><p class="type-label">Un nombre puede aparecer en varios tipos. No sumar las categorías: el total único es 947.</p>`;}
function catalogue(kind,category){
 filterOrigin=kind==='native'?'native':kind==='translations'?'translation':kind==='session'?'session':'all';filterType=kind==='native'&&category?category:'all';filterStatus='all';page=1;
 const title=kind==='native'?'Funciones nativas de DuckDB':kind==='translations'?'Traducciones Snowflake':kind==='session'?'Contexto de sesión':kind==='category'?category:'Buscar en la referencia';
 const desc=kind==='native'?'Consultá los 947 nombres registrados por DuckDB 1.5.5 y sus firmas. El catálogo incluye operadores, macros y utilidades internas.':kind==='translations'?'13 funciones reconocidas y reescritas por el traductor del emulador. Cada entrada distingue la forma verificada de sus limitaciones.':kind==='session'?'Funciones resueltas con el usuario y el rol activo de la sesión del emulador.':kind==='category'?'Funciones de esta categoría tratadas por el emulador.':'Buscá funciones, comandos o construcciones SQL y filtrá por origen, tipo o estado de soporte.';
 content.innerHTML=heading('REFERENCIA / CATÁLOGO',esc(title),desc)+(kind==='native'?notice('<strong>Catálogo del motor.</strong> Este catálogo describe el registro nativo, sin prometer sintaxis ni comportamiento de Snowflake. Algunos nombres también tienen tratamiento propio en el emulador; sus fichas indican ese cruce.'):kind==='translations'?notice('<strong>Traducción léxica.</strong> Se adaptan nombres y expresiones, no toda la gramática de Snowflake. Revisá las limitaciones antes de usar una variante.'):kind==='session'?notice('La reescritura de contexto reconoce <code>CURRENT_USER()</code> y <code>CURRENT_ROLE()</code> con paréntesis vacíos. Sus valores provienen de la sesión autenticada.'):notice('Los 997 registros incluyen 947 nombres nativos, 15 funciones del emulador y 35 referencias de sintaxis y comandos. Hay nombres compartidos entre capas; no es un conteo de funciones compatibles con Snowflake.'))+`<div id="catalogue"><div class="filter-tabs" aria-label="Filtrar por origen">${[['all','Todas'],['translation','Traducciones'],['native','DuckDB nativas'],['session','Contexto'],['reference','Sintaxis y comandos']].map(([v,l])=>`<button data-origin="${v}" class="${v===filterOrigin?'selected':''}" aria-pressed="${v===filterOrigin}">${l}</button>`).join('')}</div><div class="toolbar"><input class="filter-input" id="catalogSearch" type="search" aria-label="Buscar función por nombre o descripción" placeholder="Filtrar por nombre o descripción…" value="${esc(query)}"><select id="typeFilter" aria-label="Tipo de función"><option value="all">Todos los tipos</option>${Object.entries(types).map(([v,l])=>`<option value="${v}" ${v===filterType?'selected':''}>${l}</option>`).join('')}</select><select id="statusFilter" aria-label="Estado de soporte"><option value="all">Todos los estados</option><option value="verified">Forma verificada</option><option value="partial">Parcial</option><option value="catalog">Catalogada</option></select></div><div id="results"></div></div>`;
 content.dataset.category=kind==='category'?category:'';
 $('#catalogSearch').addEventListener('input',e=>{query=e.target.value;$('#globalSearch').value=query;page=1;renderResults()});
 $('#typeFilter').addEventListener('change',e=>{filterType=e.target.value;page=1;renderResults()});$('#statusFilter').addEventListener('change',e=>{filterStatus=e.target.value;page=1;renderResults()});renderResults();toc([['catalogue','Explorar funciones']]);
}
function renderResults(){
 const cat=content.dataset.category;
 const q=query.trim().toLowerCase();
 let items=all.filter(i=>(filterOrigin==='all'||i.origin===filterOrigin)&&(!cat||(i.origin!=='native'&&i.category===cat))&&(filterType==='all'||i.types?.includes(filterType))&&(filterStatus==='all'||i.status===filterStatus)&&(!q||`${i.name} ${i.description} ${i.category||''} ${window.DocLanguage?.translate(i.description)||''} ${window.DocLanguage?.translate(i.category)||''}`.toLowerCase().includes(q)));
 items.sort((a,b)=>a.name.localeCompare(b.name)||a.origin.localeCompare(b.origin));
 const limit=25,pages=Math.max(1,Math.ceil(items.length/limit));page=Math.min(page,pages);const subset=items.slice((page-1)*limit,page*limit);
 $('#results').innerHTML=`<div class="result-count" aria-live="polite"><span>${items.length.toLocaleString('es')} ${items.length===1?'resultado':'resultados'}</span><span>Orden alfabético · A–Z</span></div>`+(items.length?`<div class="table-wrap"><table class="catalog-table"><thead><tr><th>Entrada</th><th>Origen</th><th>Descripción</th><th>Estado</th></tr></thead><tbody>${subset.map(i=>`<tr><td class="function-name"><a href="${path(i)}">${esc(i.name)}</a><div class="type-label">${i.origin==='native'?i.types.map(t=>types[t]).join(' · '):esc(i.origin==='reference'?referenceGroups[i.category]:i.category)}</div></td><td>${badge(i.origin,i.origin==='reference'?'Sintaxis / comando':undefined)}</td><td class="description">${esc(i.description?i.description.slice(0,125)+(i.description.length>125?'…':''):'Sin descripción en el catálogo del motor.')}</td><td>${i.status==='catalog'?badge('native','Catalogada'):badge(i.status)}</td></tr>`).join('')}</tbody></table></div><div class="pager"><span>${(page-1)*limit+1}–${Math.min(page*limit,items.length)} de ${items.length}</span><div><button data-page="${page-1}" ${page===1?'disabled':''} aria-label="Página anterior">← Anterior</button><button data-page="${page+1}" ${page===pages?'disabled':''} aria-label="Página siguiente">Siguiente →</button></div></div>`:`<div class="empty"><strong>No encontramos funciones</strong><p>Probá con otro nombre o quitá los filtros.</p><button class="plain-button" id="resetFilters">Limpiar filtros</button></div>`);
 window.DocLanguage?.refresh();
}
function emulatorDetail(name){const i=emulator.find(x=>x.name===name);if(!i)return notFound();const isSession=i.origin==='session';
 content.innerHTML=`<a href="${isSession?'#session':'#translations'}" class="back-link">← ${isSession?'Contexto de sesión':'Traducciones Snowflake'}</a><p class="eyebrow">${esc(i.category)}</p><h1 class="detail-name">${esc(i.name)}</h1><div class="status-line">${badge(i.origin)} ${badge(i.status)}</div><p class="lead detail-intro">${esc(i.description)}</p>${meta()}<h2 id="syntax">Sintaxis admitida</h2>${code(i.syntax)}<h2 id="translation">${isSession?'Cómo se resuelve':'Traducción a DuckDB'}</h2>${code(i.target,isSession?'CONTEXTO DEL EMULADOR':'SQL RESULTANTE')}<h2 id="example">Ejemplo</h2>${code(i.example)}${code(i.result,'RESULTADO / REFERENCIA')}<p class="type-label">${isSession?'Valor dependiente de la sesión. Evidencia: prueba automatizada de identidad.':i.name.startsWith('CURRENT_')?'El resultado cambia según el momento de ejecución.':'Forma ejecutada durante la auditoría local del 21 oct 2026. El formato de presentación del resultado puede variar.'}</p><h2 id="limitations">Limitaciones</h2>${notice(esc(i.limitation),i.status==='partial')}<h2 id="implementation">Implementación y evidencia</h2><dl class="definitions"><dt>Origen</dt><dd>${isSession?'Contexto de sesión del emulador':'Reescritura léxica Snowflake → DuckDB'}</dd><dt>Implementación</dt><dd><code>${isSession?'pkg/query/session_context.go':'pkg/query/translator.go'}</code></dd><dt>Pruebas</dt><dd><code>${isSession?'pkg/query/session_context_test.go':'pkg/query/translator_test.go'}</code>${['DATEADD','DATEDIFF'].includes(i.name)?'<br><code>pkg/query/date_functions_test.go</code>':''}</dd><dt>Alcance</dt><dd>La evidencia cubre formas concretas, no todas las variantes ni la equivalencia completa con Snowflake.</dd></dl><div class="overview-bottom"><a href="#limits">Ver limitaciones generales →</a><a href="#native">Explorar DuckDB →</a></div>`;
 toc([['syntax','Sintaxis'],['translation',isSession?'Resolución':'Traducción'],['example','Ejemplo'],['limitations','Limitaciones'],['implementation','Implementación']]);
}
function nativeDetail(name){const i=native.find(x=>x.name===name);if(!i)return notFound();const intercepted=emulator.find(e=>e.name.toLowerCase()===i.name.toLowerCase());
 content.innerHTML=`<a href="#native" class="back-link">← Catálogo nativo de DuckDB</a><p class="eyebrow">DUCKDB / ${i.types.map(t=>types[t]).join(' · ').toUpperCase()}</p><h1 class="detail-name">${esc(i.name)}</h1><div class="status-line">${badge('native')}${badge('native','Catalogada')}</div>${meta()}${notice('<strong>Disponibilidad nativa, sin validación individual.</strong> Este nombre figura en el catálogo DuckDB de la auditoría. No se probaron todas sus firmas a través del emulador ni se afirma equivalencia con Snowflake.')}${intercepted?notice(`<strong>Este nombre también lo trata el emulador.</strong> Una llamada no cualificada pasa por nuestra ${intercepted.origin==='session'?'resolución de contexto':'traducción'}. Consultá <a href="${path(intercepted)}">${esc(intercepted.name)}</a> para conocer el comportamiento efectivo de esa llamada.`):''}<h2 id="description">Descripción del motor</h2><p class="native-description-label">Texto original de DuckDB · inglés</p><p class="native-description">${esc(i.description||'El catálogo no proporciona una descripción para esta función.')}</p><h2 id="signatures">Firmas registradas <span class="pill">${i.signatures.length}</span></h2><p class="lead">Firmas distintas del catálogo, agrupadas por nombre. Los parámetros y tipos se muestran tal como los reporta DuckDB.</p>${i.signatures.map((s,n)=>`<div class="signature"><small>FIRMA ${n+1} · ${esc(types[s.type])}</small>${code(`${i.name}(${s.parameters.replace(/^\[|\]$/g,'')})`,'PARÁMETROS DEL CATÁLOGO')}<dl class="definitions"><dt>Tipos de entrada</dt><dd><code>${esc(s.parameter_types)}</code></dd><dt>Retorno</dt><dd><code>${esc(s.return_type||'No especificado / tabular')}</code></dd>${s.varargs?`<dt>Argumentos extra</dt><dd><code>${esc(s.varargs)}</code></dd>`:''}${s.alias_of?`<dt>Alias de</dt><dd><code>${esc(s.alias_of)}</code></dd>`:''}</dl></div>`).join('')}<h2 id="scope">Alcance en el emulador</h2><p>Las funciones sin una traducción propia se conservan para que DuckDB intente ejecutarlas. La consulta completa debe usar una sintaxis aceptada por el motor y pasar por las reglas de contexto y autorización del emulador.</p>${notice('Las funciones internas, de archivos, extensiones o configuración pueden requerir recursos adicionales. Estar catalogada no demuestra que una llamada concreta funcione en todas las sesiones.',true)}<a class="inline-link" href="duckdb-functions.json" download>Descargar el catálogo original con todas las filas →</a>`;
 toc([['description','Descripción'],['signatures','Firmas registradas'],['scope','Alcance y limitaciones']]);
}
function udf(){content.innerHTML=heading('REFERENCIA / FUNCIONES DE USUARIO','Funciones de usuario SQL','Definí una función escalar con una expresión SQL y usala en SELECT, WHERE o desde un procedimiento.')+notice('<strong>Implementación local.</strong> Cada UDF se guarda en el catálogo del emulador y se respalda con una macro real de DuckDB.')+`<h2 id="create">Crear una función</h2>${code('CREATE FUNCTION area(width FLOAT, height FLOAT)\nRETURNS FLOAT\nLANGUAGE SQL\nAS $$ width * height $$;')}<p>El cuerpo es una única expresión delimitada por <code>$$</code>. <code>LANGUAGE SQL</code> es opcional.</p><h2 id="call">Invocar</h2>${code('SELECT area(3, 4);')}${code('12','RESULTADO')}<h2 id="manage">Reemplazar, listar y eliminar</h2>${code('CREATE OR REPLACE FUNCTION area(width FLOAT, height FLOAT)\nRETURNS FLOAT AS $$ width * height $$;\n\nSHOW FUNCTIONS;\n\nDROP FUNCTION IF EXISTS area(FLOAT, FLOAT);')}${notice('<strong>SHOW FUNCTIONS muestra las UDF del emulador.</strong> No incluye el catálogo nativo de DuckDB ni las traducciones incorporadas. Para esas funciones, usá esta referencia o consultá <code>duckdb_functions()</code>.')}<h2 id="udf-limitations">Limitaciones</h2><ul class="prose-list"><li>Sólo funciones escalares SQL con un cuerpo de una expresión.</li><li>Sin UDTFs, JavaScript, Python, Java ni cuerpo procedural multisentencia.</li><li>Los tipos de parámetros y retorno se almacenan como metadatos; la macro no impone esa firma como Snowflake.</li><li>No se implementa el modelo completo de sobrecargas de funciones de Snowflake.</li></ul><h2 id="evidence">Evidencia</h2><p>Las pruebas cubren llamadas en SELECT y WHERE, funciones que llaman a otras funciones, uso desde procedimientos, reemplazo, eliminación y rechazo de lenguajes no admitidos.</p><p><code>pkg/query/function_processor.go</code><br><code>pkg/query/function_processor_test.go</code></p>`;toc([['create','Crear'],['call','Invocar'],['manage','Administrar'],['udf-limitations','Limitaciones'],['evidence','Evidencia']]);}
const limitations=[['LISTAGG','La forma simple funciona; WITHIN GROUP (ORDER BY ...) falla porque no se adapta la sintaxis de agregación ordenada.'],['FLATTEN','SELECT FLATTEN([1,2]) funciona. La forma TABLE(FLATTEN(input => ...)) falla. UNNEST no reproduce la interfaz tabular de Snowflake.'],['TO_VARIANT',"Se implementa como un cast a JSON. TO_VARIANT(42) funciona; TO_VARIANT('hello') falla por JSON inválido."],['DATEADD','Convierte el argumento temporal a DATE antes de sumar el intervalo, descartando su componente horario.'],['DATEDIFF','Convierte ambos argumentos temporales a DATE antes de calcular la diferencia, descartando sus componentes horarios.'],['OBJECT_CONSTRUCT','Se traduce a json_object. No implementa todas las reglas Snowflake para NULL, wildcard ni la semántica completa de VARIANT.']];
function limits(){content.innerHTML=heading('COMPATIBILIDAD / ALCANCE','Limitaciones conocidas','El emulador ofrece un subconjunto para aprender y experimentar localmente. Una reescritura de sintaxis no demuestra equivalencia de comportamiento con Snowflake.')+`<h2 id="known">Funciones con diferencias concretas</h2><ul class="limit-list">${limitations.map(([n,t])=>`<li><strong><a href="#function/emulator/${n}">${n}</a> ${badge('partial')}</strong><p>${esc(t)}</p></li>`).join('')}</ul><h2 id="native-limitations">Catálogo nativo y variantes SQL</h2><ul class="prose-list"><li>947 nombres incluye operadores, macros, funciones internas y utilidades. No es un conteo de funciones compatibles con Snowflake.</li><li>Las 2950 filas originales incluyen sobrecargas y variantes del catálogo. No se verificó cada firma por separado.</li><li>Funciones de ventana y otras expresiones especiales no quedan representadas completamente por duckdb_functions().</li><li>Las funciones de extensiones, archivos y configuración pueden requerir recursos o permisos adicionales.</li><li>Los tipos, NULL, coerciones, orden, precisión y zonas horarias se resuelven según DuckDB, salvo donde el emulador interviene explícitamente.</li></ul><h2 id="parser">Alcance del traductor</h2><p>La traducción es léxica. Reconoce llamadas concretas y conserva los literales, comentarios y nombres cualificados. No valida toda la gramática de Snowflake. Algunas pruebas sólo verifican el SQL transformado; la ejecución debe comprobarse por separado.</p><h2 id="other">Otros límites del proyecto</h2><p>Las UDF se limitan a expresiones escalares SQL. Los procedimientos, streams, tareas, stages y tablas dinámicas tienen subconjuntos propios y no se incluyen en este conteo de funciones.</p><div class="overview-bottom"><a href="#translations">Consultar traducciones →</a><a href="#method">Ver metodología →</a></div>`;toc([['known','Diferencias por función'],['native-limitations','Catálogo nativo'],['parser','Traductor'],['other','Otros límites']]);}
function method(){content.innerHTML=heading('INVENTARIO / METODOLOGÍA','Cómo se verificó','Una instantánea reproducible del motor y una revisión del código del emulador, con evidencia separada para cada capa.')+`<h2 id="snapshot">Instantánea del 21 de octubre de 2026</h2><dl class="definitions"><dt>Motor</dt><dd>DuckDB 1.5.5</dd><dt>Driver Go</dt><dd><code>github.com/duckdb/duckdb-go/v2 v2.10505.0</code></dd><dt>Entorno</dt><dd>Base nueva en memoria. Sin instalar extensiones adicionales.</dd><dt>Resultados</dt><dd>947 nombres únicos · 2950 filas de catálogo · 13 traducciones · 2 funciones de contexto.</dd></dl><h2 id="reproduce">Consultar el catálogo</h2>${code("SELECT function_type,\n       COUNT(DISTINCT function_name) AS names,\n       COUNT(*) AS catalog_rows\nFROM duckdb_functions()\nGROUP BY function_type\nORDER BY function_type;")}${code('SELECT function_name, function_type, description,\n       parameters, parameter_types, return_type, varargs, alias_of\nFROM duckdb_functions()\nORDER BY function_type, function_name, parameter_types;')}<h2 id="validation">Evidencia de ejecución</h2><p>Se ejecutaron formas simples de las traducciones a través del Executor y se registraron los fallos de variantes que aparecen en esta referencia. Las funciones de contexto tienen pruebas automatizadas.</p><p>También se verificaron ejemplos nativos de <code>ABS</code>, <code>UPPER</code>, <code>LENGTH</code>, <code>ROUND</code>, <code>COALESCE</code> y <code>ARRAY_AGG</code>, además de ventanas con <code>ROW_NUMBER</code>, <code>RANK</code>, <code>DENSE_RANK</code>, <code>LAG</code> y <code>LEAD</code>.</p><p>Las pruebas focalizadas y la suite completa <code>go test ./...</code> pasaron durante la auditoría del 21 de octubre. Eso no equivale a haber ejecutado todas las firmas del catálogo.</p><h2 id="counts">Interpretar los números</h2><p>Los nombres se pueden repetir entre tipos del motor y entre el catálogo DuckDB y las traducciones del emulador. La referencia conserva ambos orígenes para explicar cómo se resuelven. No sumar estos conteos como funciones distintas compatibles con Snowflake.</p>${nativeTypes()}<h2 id="downloads">Datos y fuentes</h2><ul class="prose-list"><li><a href="duckdb-functions.json" download>Catálogo original JSON · parámetros, retornos, descripciones y alias</a></li><li><a href="inventario-funciones.md" download>Informe completo de la auditoría</a></li><li><a href="https://docs.snowflake.com/en/sql-reference/functions" target="_blank" rel="noopener">Referencia de funciones de Snowflake</a> · inspiración para la organización de esta documentación.</li></ul>${notice('Esta página es una instantánea, no una consulta en vivo al servidor. Si cambia la versión del motor o el traductor, regenerá y verificá el inventario antes de actualizar el alcance publicado.')}`;toc([['snapshot','Versión auditada'],['reproduce','Reproducir'],['validation','Evidencia'],['counts','Conteos'],['downloads','Descargas']]);}
const referenceGroups={query:'Sintaxis de consultas',dml:'Manipulación de datos',loading:'Carga de datos y stages',ddl:'Tablas, vistas y namespaces',session:'Sesión y transacciones',compute:'Warehouses',security:'Usuarios, roles y permisos',automation:'Streams, tareas y refrescos',programming:'Procedimientos y scripting',types:'Tipos de datos'};
function sqlIndex(category){
 const items=references.filter(i=>!category||i.category===category);
 content.innerHTML=heading('REFERENCIA / SINTAXIS Y COMANDOS',referenceGroups[category]||'Comandos y sintaxis SQL','Referencia del subconjunto implementado en el emulador. Las funciones escalares, las construcciones de consulta y los comandos son categorías distintas.')+notice('<strong>Alcance verificado por categoría.</strong> Las fichas describen las formas documentadas en el código y sus pruebas; no equivalen a todo el SQL de Snowflake.')+`<div class="sql-summary">${Object.entries(referenceGroups).map(([id,label])=>`<a href="#sql/${id}">${label}</a>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Entrada</th><th>Categoría</th><th>Descripción</th></tr></thead><tbody>${items.map(i=>`<tr><td class="function-name"><a href="#statement/${i.id}">${esc(i.name)}</a></td><td>${referenceGroups[i.category]}</td><td>${esc(i.description.es)}</td></tr>`).join('')}</tbody></table></div><h2 id="sql-scope">Alcance de esta referencia</h2><p>Las construcciones SQL estándar se ejecutan en DuckDB; los procesadores del emulador agregan resolución de nombres, contexto y subconjuntos propios. No se anuncian como disponibles comandos de Snowflake que no tengan respaldo en el proyecto.</p><p class="reference-evidence">Revisión de comandos: 24 oct 2026. Catálogo de funciones: auditoría del 21 oct 2026.</p>`;
 toc([['sql-scope','Alcance de la referencia']]);
}
function statementDetail(id){
 const i=references.find(e=>e.id===id);if(!i)return notFound();
 content.innerHTML=`<a class="back-link" href="#sql/${i.category}">← ${referenceGroups[i.category]}</a><p class="eyebrow">REFERENCIA / ${referenceGroups[i.category]}</p><h1>${esc(i.name)}</h1><div class="status-line">${badge('partial','Subconjunto documentado')}</div><p class="lead">${esc(i.description.es)}</p><div class="page-meta"><span>Referencia SQL</span><span>Revisión · 24 oct 2026</span></div><h2 id="syntax">Sintaxis documentada</h2>${code(i.syntax)}<h2 id="example">Ejemplo</h2>${code(i.example)}<p class="type-label">Los ejemplos con objetos requieren que existan las tablas, namespaces y warehouse seleccionados, salvo las sentencias que los crean.</p>${id==='copy-into'?copyNotes():''}${id==='with'?`<h2 id="with-notes">Uso de CTE</h2><p>Una CTE existe sólo dentro de su sentencia. Puede nombrar columnas y referenciar CTE anteriores. El emulador protege esos alias para que no se confundan con tablas físicas al resolver nombres.</p>${code('CREATE TEMPORARY TABLE doubled AS\nWITH base AS (SELECT column1 AS n FROM VALUES (1), (2))\nSELECT n * 2 AS n FROM base;')}<p>Las pruebas ejecutadas cubren CTE simples, múltiples CTE encadenadas y CTAS con y sin paréntesis. No se extiende esa evidencia a todas las formas recursivas de Snowflake.</p><a href="https://docs.snowflake.com/en/sql-reference/constructs/with" target="_blank" rel="noopener">Referencia oficial de WITH en Snowflake ↗</a>`:''}<h2 id="limitations">Limitaciones del emulador</h2>${notice(esc(i.limitations.es),true)}<h2 id="implementation">Implementación y evidencia</h2><p class="reference-evidence">Esta ficha se revisó contra el código del proyecto el 24 de octubre de 2026. La existencia de un parser o clasificador no demuestra que todas las variantes se ejecuten.</p><p><a href="https://github.com/OswaldOniSango/snowflake-emulator/blob/58506c13b6535b1780c544f68bdb5726eb5407a7/${i.source}" target="_blank" rel="noopener"><code>${esc(i.source)}</code> ↗</a></p>${['copy-into','with'].includes(id)?'<p class="reference-evidence">Se ejecutaron las pruebas focalizadas de COPY y CTE durante esta actualización: resultado correcto.</p>':''}<div class="overview-bottom"><a href="#sql">Ver todos los comandos →</a><a href="#limits">Limitaciones generales →</a></div>`;
 toc([['syntax','Sintaxis'],['example','Ejemplo'],...(id==='copy-into'?[['copy-options','Opciones y diferencias']]:id==='with'?[['with-notes','Uso de CTE']]:[]),['limitations','Limitaciones'],['implementation','Evidencia']]);
}
function copyNotes(){return `<h2 id="copy-options">Opciones y diferencias</h2><div class="table-wrap"><table><thead><tr><th>Opción</th><th>Comportamiento implementado</th></tr></thead><tbody><tr><td><code>TYPE = CSV</code></td><td>Formato predeterminado. Usa separador coma; admite FIELD_DELIMITER, SKIP_HEADER y TRIM_SPACE = TRUE. Un valor vacío se inserta como NULL.</td></tr><tr><td><code>TYPE = JSON</code></td><td>Lee un objeto o un array JSON completo. Inserta cada registro serializado en una sola columna. STRIP_OUTER_ARRAY = TRUE extrae los objetos del array. No es un cargador JSON Lines.</td></tr><tr><td><code>PATTERN</code></td><td>Glob aplicado al nombre base del archivo, por ejemplo '*.csv'; no una expresión regular Snowflake.</td></tr><tr><td><code>ON_ERROR</code></td><td>ABORT detiene la carga; CONTINUE y SKIP_FILE continúan con el siguiente archivo. Las filas ya insertadas pueden permanecer: no se revierte automáticamente el archivo ni se garantiza atomicidad.</td></tr><tr><td><code>PURGE = TRUE</code></td><td>Elimina los archivos cargados correctamente. Sin PURGE, repetir COPY vuelve a insertar los datos porque no hay historial de cargas.</td></tr><tr><td><code>VALIDATION_MODE</code></td><td>Se reconoce el texto de la opción pero no omite las inserciones. No se ofrece un modo seguro de validación sin escritura.</td></tr><tr><td><code>FILES / NULL_IF / RECORD_DELIMITER</code></td><td>FILES y NULL_IF no se interpretan desde SQL; RECORD_DELIMITER se parsea pero no se aplica al lector CSV. No se anuncian como opciones soportadas.</td></tr></tbody></table></div><h3>Preparar tabla y stage</h3>${code('CREATE TABLE users (id INTEGER, name VARCHAR);\nCREATE STAGE users_stage;\nLIST @users_stage;')}<p>Subí un CSV al stage desde el explorador de objetos o la API HTTP del emulador antes de ejecutar COPY. No se usa PUT.</p><h3>Ejemplo JSON</h3>${code('CREATE TABLE events (payload VARCHAR);\nCOPY INTO events FROM @events_stage\nFILE_FORMAT = (TYPE = JSON STRIP_OUTER_ARRAY = TRUE);')}<p>El stage events_stage debe existir y contener un archivo JSON. Para tablas con varias columnas no hay mapeo automático de claves JSON a columnas.</p>`;}

function notFound(){content.innerHTML=heading('REFERENCIA','Página no encontrada','No hay una entrada con ese nombre en esta instantánea.')+'<a href="#catalog">Volver al catálogo →</a>';toc([]);}
function render(){
 const [raw,params]=location.hash.slice(1).split('?');const parts=(raw||'overview').split('/').map(x=>{try{return decodeURIComponent(x)}catch{return x}});route=parts[0];codeCount=0;codeMap={};content.dataset.category='';
 document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(route==='statement'?'sql':route)));document.querySelectorAll('[data-top]').forEach(a=>a.classList.toggle('active',a.dataset.top===(['limits','method','overview'].includes(route)?route:'catalog')));
 $('#sidebar').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false');
 if(route==='overview')overview();else if(['catalog','translations','session','native','category'].includes(route))catalogue(route,parts[1]);else if(route==='function')parts[1]==='native'?nativeDetail(parts[2]):emulatorDetail(parts[2]);else if(route==='sql')sqlIndex(parts[1]);else if(route==='statement')statementDetail(parts[1]);else if(route==='udf')udf();else if(route==='limits')limits();else if(route==='method')method();else notFound();
 document.title=($('#content h1')?.textContent||'Referencia SQL')+' | Snowflake Emulator';$('#breadcrumbs').innerHTML=`<a href="#overview">Documentación</a> <span>›</span> <a href="#catalog">Referencia SQL</a> <span>›</span> ${esc($('#content h1')?.textContent||'Funciones')}`;
 window.DocLanguage?.refresh();
 const section=new URLSearchParams(params).get('section');if(section)document.getElementById(section)?.scrollIntoView();else window.scrollTo({top:0});
}
function toast(s){$('#toast').textContent=s;window.DocLanguage?.refresh();$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}
document.addEventListener('click',async e=>{
 if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return}
 const copyButton=e.target.closest('[data-copy]');if(copyButton){try{await navigator.clipboard.writeText(codeMap[copyButton.dataset.copy]);toast('SQL copiado al portapapeles')}catch{toast('No se pudo copiar. Seleccioná el código para copiarlo.')}return}
 const originButton=e.target.closest('[data-origin]');if(originButton){filterOrigin=originButton.dataset.origin;filterType='all';$('#typeFilter').value='all';page=1;document.querySelectorAll('[data-origin]').forEach(b=>{b.classList.toggle('selected',b===originButton);b.setAttribute('aria-pressed',b===originButton)});renderResults();return}
 const pageButton=e.target.closest('[data-page]');if(pageButton&&!pageButton.disabled){page=Number(pageButton.dataset.page);renderResults();$('#catalogue').scrollIntoView({block:'start'});return}
 if(e.target.closest('#resetFilters')){query='';filterOrigin='all';filterType='all';filterStatus='all';content.dataset.category='';$('#catalogSearch').value='';$('#globalSearch').value='';$('#typeFilter').value='all';$('#statusFilter').value='all';document.querySelectorAll('[data-origin]').forEach(b=>{b.classList.toggle('selected',b.dataset.origin==='all');b.setAttribute('aria-pressed',b.dataset.origin==='all')});renderResults()}
 const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'})}
});
let searchTimer;$('#globalSearch').addEventListener('input',e=>{query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(route!=='catalog')location.hash='catalog';else{$('#catalogSearch').value=query;page=1;renderResults()}},200)});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#globalSearch').focus()}if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false');$('#globalSearch').blur()}});
$('#mobileMenu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#mobileMenu').setAttribute('aria-expanded',String(open))});
try{if(localStorage.getItem('emulator-docs-theme')==='dark')document.body.classList.add('dark')}catch{}
$('#theme').addEventListener('click',()=>{const dark=document.body.classList.toggle('dark');try{localStorage.setItem('emulator-docs-theme',dark?'dark':'light')}catch{}$('#theme').setAttribute('aria-label',dark?'Activar tema claro':'Activar tema oscuro');window.DocLanguage?.refresh()});
Promise.all([fetch('native.json').then(r=>{if(!r.ok)throw Error('catálogo');return r.json()}),fetch('emulator.json').then(r=>{if(!r.ok)throw Error('traducciones');return r.json()}),fetch('reference.json').then(r=>{if(!r.ok)throw Error('referencia SQL');return r.json()})]).then(([n,e,r])=>{native=n.map(i=>({...i,origin:'native',status:'catalog'}));emulator=e;references=r.entries;all=[...emulator,...native,...references.map(i=>({...i,origin:'reference',status:'partial',description:i.description.es}))];window.addEventListener('hashchange',render);render()}).catch(()=>{content.innerHTML='<h1>No se pudo cargar el inventario</h1><p>Revisá la conexión y volvé a cargar la página.</p><button class="plain-button" onclick="location.reload()">Reintentar</button>';window.DocLanguage?.refresh()});
